import {language,t,setLanguage,translate} from './i18n.js?v=b6d94cdf4ffb';
import {guides} from './guides.js?v=b6d94cdf4ffb';
import {initAuth,authHeaders,refreshAuthLabels,openAuth,authProvider} from './auth.js?v=b6d94cdf4ffb';
const $=id=>document.getElementById(id), el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
const state={signedIn:false,profile:null,moderator:false,questions:[],helpers:[],conversations:[],active:null,messages:[],hasOlder:false,hasMore:false,view:'community',offerId:null,reportTarget:null};
let toastTimer,toastKey,confirmAction,refreshing=false;
function toast(key){toastKey=key;$('toast').textContent=t(key);$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',5000);}
async function api(path,method='GET',data){const res=await fetch('/api'+path,{method,credentials:'same-origin',cache:'no-store',headers:{...await authHeaders(),...(method==='GET'?{}:{'Content-Type':'application/json','X-Common-Ground':'1'})},body:data===undefined?undefined:JSON.stringify(data)});let value;try{value=await res.json();}catch{throw Error('unavailable');}if(!res.ok)throw Error(value.error||'unavailable');return value;}
function button(key,action,cls='secondary'){const b=el('button',cls,t(key));b.type='button';b.addEventListener('click',()=>run(b,action));return b;}
async function run(control,action){if(control?.disabled)return;if(control)control.disabled=true;try{await action();}catch(e){toast(e.message);if(e.message==='signIn'||e.message==='finishOnboarding')await bootstrap(false);}finally{if(control)control.disabled=false;}}
function bindForm(id,action){$(id).addEventListener('submit',e=>{e.preventDefault();run($(id).querySelector('button[type=submit],button:not([type])'),action);});}
function status(error){$('load-status').hidden=!error;if(error)$('load-status').textContent=t(error);}
function requireMember(){if(state.profile)return true;if(state.signedIn)openProfile();else{$('welcome').scrollIntoView({behavior:'instant',block:'center'});if(authProvider()==='firebase')openAuth();else toast('signIn');}return false;}
function showView(view){if(view==='conversations'&&!requireMember())return;state.view=view;$('community-view').hidden=view!=='community';$('conversations-view').hidden=view!=='conversations';$('community-nav').classList.toggle('active',view==='community');$('conversation-nav').classList.toggle('active',view==='conversations');if(view==='conversations')renderChat();}
function showTab(which,focus=false){for(const key of ['questions','guide']){const active=key===which;$(key+'-tab').setAttribute('aria-selected',String(active));$(key+'-tab').tabIndex=active?0:-1;$(key+'-pane').hidden=!active;}if(focus)$(which+'-tab').focus();}
function renderAccount(){document.querySelectorAll('.sign-in').forEach(e=>e.hidden=state.signedIn);$('sign-out').hidden=!state.signedIn;$('profile-button').hidden=!state.profile;$('welcome').hidden=!!state.profile;$('onboard-button').hidden=!state.signedIn;$('question-fields').disabled=!state.profile;$('ask-status').textContent=!state.profile?t(state.signedIn?'finishOnboarding':'signIn'):state.profile.name+' · '+t(state.profile.role);$('chat-count').textContent=state.conversations.length;refreshAuthLabels();}
function renderQuestions(){const feed=$('question-feed');feed.replaceChildren();$('question-count').textContent=state.questions.length;$('more-questions').hidden=!state.hasMore;
 if(!state.profile){feed.append(el('p','empty',t('joinFeed')));return;}
 const qs=state.questions.filter(q=>!$('filter').value||q.topic===$('filter').value);if(!qs.length)feed.append(el('p','empty',t('noQuestions')));
 for(const q of qs){const card=el('article','question'),meta=el('div','question-meta');meta.append(el('span','chip',t(q.topic)),el('span','',q.name+' · '+t(q.role)+(q.university?' · '+q.university:'')));card.append(meta,el('h3','',q.title),el('p','',q.body));const actions=el('div','question-actions');
 if(!q.mine&&!q.offers.some(o=>o.mine)){actions.append(button('offer',()=>{state.offerId=q.id;$('offer-question').textContent=q.title;$('offer-form').reset();$('offer-dialog').showModal();},'primary'));}
 actions.append(button('guide',()=>showTab('guide'),'text-button'));if(!q.mine){actions.append(button('report',()=>openReport({postId:q.id}),'text-button'),button('block',()=>confirm('blockConfirm',async()=>{await api('/blocks','POST',{userId:q.authorId});await refresh();}),'text-button'));}card.append(actions);
 for(const o of q.offers){const offer=el('div','offer');offer.append(el('strong','',t(o.mine?'yourOffer':'offerReceived')+' · '+o.name),el('p','',o.text),el('span','small',t(o.status)));if(q.mine&&o.status==='pending'){const a=el('div','offer-actions');a.append(button('accept',async()=>{const r=await api('/offers/'+o.id+'/accept','POST',{});await refresh();await openConversation(r.conversationId);},'primary'),button('decline',async()=>{await api('/offers/'+o.id+'/decline','POST',{});await refresh();}));offer.append(a);}if(o.status==='accepted'){offer.append(button('seeChat',async()=>{await refresh();const c=state.conversations.find(c=>c.id===o.conversationId);if(c)await openConversation(c.id);else toast('notFound');},'text-button'));}card.append(offer);}feed.append(card);}
}
function renderHelpers(){const box=$('helper-list');box.replaceChildren();if(!state.profile||!state.helpers.length){box.append(el('p','small',t(state.profile?'noHelpers':'joinFeed')));return;}for(const p of state.helpers.slice(0,6)){const c=el('div','helper-card'),d=el('div');d.append(el('strong','',p.name),el('span','',t(p.role)+(p.university?' · '+p.university:'')));c.append(el('span','avatar blue',Array.from(p.name).slice(0,2).join('')),d);box.append(c);}}
function guideCard(g,compact=false){const c=g[language],card=el('article','guide-card');card.append(el('h3','',c.title),el('p','',c.intro));const ul=el('ul');c.steps.forEach(s=>ul.append(el('li','',s)));card.append(ul);if(!compact)card.append(el('strong','small',t('prompt')),el('blockquote','',c.prompt));const a=el('a','',t('source'));a.href=g.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a,el('p','source-label',g.source));return card;}
function renderGuides(){const search=$('guide-search').value.trim().toLowerCase(),box=$('guide-list');box.replaceChildren();const list=guides.filter(g=>(g.keywords+' '+JSON.stringify(g.en)+' '+JSON.stringify(g.zh)).toLowerCase().includes(search));list.forEach(g=>box.append(guideCard(g)));if(!list.length)box.append(el('p','empty',t('noGuides')));const chat=$('chat-guides');chat.replaceChildren();for(const g of guides){const b=button(g[language].title,async()=>{if(!state.active)return;await api('/conversations/'+state.active+'/messages','POST',{body:g[language].prompt,guideId:g.id});await loadMessages();toast('guideShared');});b.disabled=!state.active||!!activeConversation()?.ended;chat.append(b);}}
function activeConversation(){return state.conversations.find(c=>c.id===state.active);}
function renderConversations(){const list=$('conversation-list');list.replaceChildren();if(!state.conversations.length)list.append(el('p','small',t('noConversations')));for(const c of state.conversations){const b=button(c.name,()=>openConversation(c.id),'conversation-item');b.replaceChildren(el('strong','',c.name),el('span','',c.context));b.setAttribute('aria-current',String(c.id===state.active));list.append(b);}$('chat-count').textContent=state.conversations.length;}
function renderChat(){const c=activeConversation();$('chat-empty').hidden=!!c;$('chat-content').hidden=!c;if(!c){renderGuides();return;}$('chat-name').textContent=c.name;$('chat-context').textContent=c.context;$('close-chat').hidden=!!c.ended;$('message-form').hidden=!!c.ended;$('chat-status').textContent=c.ended?t('ended'):t('chatPrivacy');$('older-messages').hidden=!state.hasOlder;const box=$('messages'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<70;box.replaceChildren();for(const m of state.messages){const mine=m.authorId===state.profile.id,item=el('div','message'+(mine?' mine':'')+(m.guideId?' reference':''));item.append(el('strong','small',mine?t('you'):c.name),el('p','',m.body));const g=guides.find(g=>g.id===m.guideId);if(g)item.append(guideCard(g,true));const time=el('time','',new Intl.DateTimeFormat(language==='zh'?'zh-CN':'en',{dateStyle:'short',timeStyle:'short'}).format(new Date(m.created)));time.dateTime=new Date(m.created).toISOString();item.append(time);box.append(item);}if(atBottom)box.scrollTop=box.scrollHeight;renderGuides();}
async function openConversation(id){if(state.active!==id){state.messages=[];state.hasOlder=false;}state.active=id;showView('conversations');await loadMessages(true);renderConversations();}
async function loadMessages(initial=false,older=false){const id=state.active;if(!id)return;let query='';if(older&&state.messages.length)query='?before='+state.messages[0].id;else if(!initial&&state.messages.length)query='?after='+state.messages.at(-1).id;const r=await api('/conversations/'+id+'/messages'+query);if(state.active!==id)return;const c=activeConversation();if(c)c.ended=r.ended;const dedup=new Map([...state.messages,...r.messages].map(m=>[m.id,m]));state.messages=[...dedup.values()].sort((a,b)=>a.id-b.id);if(initial||older)state.hasOlder=r.hasMore;renderChat();if(query.startsWith('?after')&&r.hasMore)await loadMessages();}
async function loadQuestions(more=false){let suffix='';if(more&&state.questions.length){const last=state.questions.at(-1);suffix='?before='+last.created+'&beforeId='+encodeURIComponent(last.id);}const r=await api('/questions'+suffix);state.questions=more?[...state.questions,...r.questions]:r.questions;state.hasMore=r.hasMore;renderQuestions();}
async function refresh(){if(!state.profile||refreshing)return;refreshing=true;try{const [q,h,c]=await Promise.all([api('/questions'),api('/helpers'),api('/conversations')]);state.questions=q.questions;state.hasMore=q.hasMore;state.helpers=h.helpers;state.conversations=c.conversations;if(state.active&&!activeConversation()){state.active=null;state.messages=[];}status(null);renderAccount();renderQuestions();renderHelpers();renderConversations();if(state.active)await loadMessages();else renderChat();}catch(e){status(e.message);throw e;}finally{refreshing=false;}}
async function bootstrap(auto=true){try{const r=await api('/me');Object.assign(state,r);renderAccount();renderQuestions();renderHelpers();if(state.profile)await refresh();else if(state.signedIn&&auto)openProfile();status(null);}catch(e){status(e.message);renderAccount();renderQuestions();}}
async function openProfile(){if(!state.signedIn){toast('signIn');return;}const p=state.profile;$('profile-name').value=p?.name??'';$('profile-group').value=p?.group??'neurodivergent';$('profile-role').value=p?.role??'Student';$('profile-university').value=p?.university??'';$('profile-consent').checked=!!p;$('profile-submit').textContent=t(p?'editProfile':'saveProfile');$('profile-extra').hidden=!p;$('moderation-button').hidden=!state.moderator;$('profile-dialog').showModal();if(p)await loadBlocks();}
async function loadBlocks(){const r=await api('/blocks'),box=$('blocked-list');box.replaceChildren();if(!r.blocks.length)box.append(el('p','small',t('noBlocks')));for(const p of r.blocks){const row=el('div','blocked-row');row.append(el('span','',p.name),button('unblock',async()=>{await api('/blocks/'+encodeURIComponent(p.id),'DELETE');await loadBlocks();await refresh();},'text-button'));box.append(row);}}
function openReport(target){state.reportTarget=target;$('report-form').reset();$('report-dialog').showModal();}
function confirm(key,action){$('confirm-text').textContent=t(key);confirmAction=action;$('confirm-dialog').showModal();}
async function loadReports(){const r=await api('/reports'),box=$('report-list');box.replaceChildren();if(!r.reports.length)box.append(el('p','small',t('noReports')));for(const report of r.reports){const card=el('article','guide-card');card.append(el('p','',report.reason),el('p','small',new Date(report.created).toLocaleString()));if(report.title)card.append(el('h3','',report.title),el('p','',report.body));if(report.conversation_id)card.append(button('viewContext',async()=>{const r=await api('/reports/'+report.id);const context=el('div');for(const m of r.messages)context.append(el('strong','small',m.name),el('p','',m.body));card.append(context);},'text-button'));card.append(button('resolved',async()=>{await api('/reports/'+report.id+'/resolve','POST',{});await loadReports();}));box.append(card);}}
document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{setLanguage(b.dataset.language);if(toastKey)$('toast').textContent=t(toastKey);renderAccount();renderQuestions();renderHelpers();renderConversations();renderGuides();renderChat();$('profile-submit').textContent=t(state.profile?'editProfile':'saveProfile');}));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
$('community-nav').onclick=()=>showView('community');$('conversation-nav').onclick=()=>showView('conversations');$('back-community').onclick=()=>showView('community');
for(const key of ['questions','guide']){$(key+'-tab').onclick=()=>showTab(key);$(key+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();showTab(e.key==='Home'?'questions':e.key==='End'?'guide':key==='guide'?'questions':'guide',true);}};}
$('open-guide').onclick=()=>{showTab('guide');$('guide-tab').scrollIntoView({behavior:'instant',block:'start'});};$('help-focus').onclick=()=>{showTab('questions');$('questions-tab').focus();};$('filter').onchange=renderQuestions;$('guide-search').oninput=renderGuides;
$('refresh').onclick=()=>run($('refresh'),refresh);$('more-questions').onclick=()=>run($('more-questions'),()=>loadQuestions(true));$('older-messages').onclick=()=>run($('older-messages'),()=>loadMessages(false,true));
$('profile-button').onclick=()=>run(null,openProfile);$('onboard-button').onclick=()=>run(null,openProfile);$('privacy-button').onclick=()=>$('privacy-dialog').showModal();
$('rights-button').onclick=()=>$('rights-dialog').showModal();
$('report-chat').onclick=()=>openReport({conversationId:state.active});$('block-chat').onclick=()=>{const c=activeConversation();if(c)confirm('blockConfirm',async()=>{await api('/blocks','POST',{userId:c.partnerId});await refresh();});};
$('close-chat').onclick=()=>confirm('endConfirm',async()=>{await api('/conversations/'+state.active+'/end','POST',{});await refresh();});
$('confirm-button').onclick=()=>run($('confirm-button'),async()=>{await confirmAction?.();$('confirm-dialog').close();});
$('moderation-button').onclick=()=>run(null,async()=>{$('moderation-dialog').showModal();await loadReports();});
bindForm('profile-form',async()=>{const r=await api('/profile','PUT',{name:$('profile-name').value,group:$('profile-group').value,role:$('profile-role').value,university:$('profile-university').value,language,consent:$('profile-consent').checked});state.profile=r.profile;$('profile-dialog').close();await refresh();toast('saved');});
bindForm('question-form',async()=>{if(!requireMember())return;await api('/questions','POST',{title:$('question-title').value,body:$('question-body').value,topic:$('topic').value});$('question-form').reset();await refresh();showTab('questions');toast('posted');});
bindForm('offer-form',async()=>{await api('/questions/'+state.offerId+'/offers','POST',{message:$('offer-message').value});$('offer-dialog').close();await refresh();toast('offered');});
bindForm('message-form',async()=>{if(!state.active)return;await api('/conversations/'+state.active+'/messages','POST',{body:$('message').value});$('message').value='';await loadMessages();toast('sent');});
bindForm('report-form',async()=>{await api('/reports','POST',{...state.reportTarget,reason:$('report-reason').value});$('report-dialog').close();toast('reported');});
translate();renderGuides();renderAccount();renderQuestions();
initAuth(async()=>{Object.assign(state,{signedIn:false,profile:null,moderator:false,questions:[],helpers:[],conversations:[],active:null,messages:[]});showView('community');renderAccount();renderQuestions();renderHelpers();renderConversations();await bootstrap();}).then(()=>bootstrap()).catch(e=>status(e.message));
setInterval(()=>{if(document.visibilityState==='visible'&&state.profile&&!document.querySelector('dialog[open]'))refresh().catch(()=>{});},15000);

// Read-only browser tools use the same visible guide and server-authorized feed.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'search_shared_guide',title:'Search shared guide',description:'Search the bilingual guide, show matching entries, and return their titles and sources. Does not send a message.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.query!=='string'||input.query.length>100||Object.keys(input).some(k=>k!=='query'))throw Error('invalidInput');$('guide-search').value=input.query;showView('community');showTab('guide');renderGuides();const q=input.query.toLowerCase();return {guides:guides.filter(g=>(g.keywords+' '+JSON.stringify(g.en)+' '+JSON.stringify(g.zh)).toLowerCase().includes(q)).map(g=>({id:g.id,title:g[language].title,source:g.url}))};}});
 register({name:'read_community_questions',title:'Read community questions',description:'Read the latest questions available to the signed-in member. Does not post or send anything. Requires a completed profile.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('invalidInput');if(!state.profile)throw Error('signIn');await loadQuestions();return {questions:state.questions.slice(0,20).map(q=>({id:q.id,title:q.title,topic:q.topic}))};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
